#!/usr/bin/env bash
# Part of the Newsroom installer library; sourced by common.sh, never executed.

# --- Install steps ---------------------------------------------------------

nr_install_cli() {
  local bin_dir="$1"
  [ "$NR_DRY_RUN" = "1" ] && { nr_info "would install the newsroom CLI into $bin_dir"; return 0; }
  mkdir -p "$bin_dir"
  local launcher="$bin_dir/newsroom"
  cat > "$launcher" <<EOF
#!/usr/bin/env bash
# Generated by install.sh. Runs the control CLI from the checkout that
# installed it; re-run install.sh if the repository moves.
exec "$NR_REPO_ROOT/bin/newsroom.sh" "\$@"
EOF
  chmod 755 "$launcher"
  nr_ok "installed CLI: $launcher"
}

nr_download_models() {
  local force="${1:-0}"
  if [ "$NR_DOWNLOAD_MODELS" = "0" ]; then
    nr_info "skipping model download (--no-models)"
    return 0
  fi

  local mode ollama_model piper_model whisper_model
  mode="$(nr_env_get NEWSROOM_MODE)"
  mode="${mode:-demo}"
  if [ "$mode" = "demo" ]; then
    nr_info "demo mode needs no models; skipping the download (use --mode local for real local AI)"
    return 0
  fi
  if [ "$force" = "0" ] && [ "$(nr_state_get MODELS_DOWNLOADED)" = "1" ]; then
    nr_ok "local models already downloaded"
    return 0
  fi

  ollama_model="$(nr_env_get OLLAMA_MODEL)"
  ollama_model="${ollama_model:-qwen2.5:3b-instruct}"
  piper_model="$(nr_env_get PIPER_MODEL)"
  piper_model="${piper_model:-es_ES-davefx-medium}"
  whisper_model="$(nr_env_get WHISPER_MODEL)"
  whisper_model="${whisper_model:-small}"

  nr_info "local model download sizes (approximate):"
  nr_info "  Ollama ${ollama_model}: ~2 GB"
  nr_info "  Whisper ${whisper_model}: ~0.5 GB"
  nr_info "  Piper ${piper_model}: ~60 MB"
  nr_info "Downloading local models; this can take a while"

  nr_run_compose --profile local run --rm model-init
  # `ollama pull` needs the server; start only that service for the download
  # and leave the full stack start to the installer's normal step.
  if ! nr_compose ps --status running --services 2>/dev/null | grep -qx ollama; then
    nr_run_compose --profile local up -d ollama
  fi
  if ! nr_run_compose --profile local exec -T ollama /bin/ollama pull "$ollama_model"; then
    nr_warn "Ollama model pull failed; run 'newsroom models pull' after the stack is healthy"
  fi
  nr_state_set MODELS_DOWNLOADED 1
  nr_ok "local models ready"
}

nr_run_migrations() {
  if [ "$(nr_state_get MIGRATIONS_APPLIED)" = "1" ]; then
    nr_ok "database migrations already applied"
    return 0
  fi
  nr_info "applying database migrations"
  nr_run_compose run --rm migrate
  nr_state_set MIGRATIONS_APPLIED 1
}

nr_prompt_admin_email() {
  local email="${NEWSROOM_ADMIN_EMAIL:-$(nr_env_get NEWSROOM_ADMIN_EMAIL)}"
  if [ -n "$email" ]; then
    printf '%s' "$email"
    return 0
  fi
  if nr_is_interactive; then
    printf 'Administrator email [admin@example.local]: ' >&2
    local answer=""
    IFS= read -r answer
    printf '%s' "${answer:-admin@example.local}"
    return 0
  fi
  printf 'admin@example.local'
}

nr_create_admin() {
  if [ "$(nr_state_get ADMIN_CREATED)" = "1" ]; then
    NR_ADMIN_STATE="existing"
    NR_ADMIN_EMAIL_VALUE="$(nr_env_get NEWSROOM_ADMIN_EMAIL)"
    nr_ok "administrator account already initialized"
    return 0
  fi

  local email password generated=0
  email="$(nr_prompt_admin_email)"
  password="${NEWSROOM_ADMIN_PASSWORD:-}"

  if [ -z "$password" ]; then
    if nr_is_interactive; then
      local confirm=""
      password="$(nr_read_secret "Administrator password (min 8 chars): ")"
      confirm="$(nr_read_secret "Repeat administrator password: ")"
      if [ "$password" != "$confirm" ]; then
        nr_die "passwords do not match"
      fi
      unset confirm
    else
      password="$(nr_generate_password)"
      generated=1
    fi
  fi

  if [ "${#password}" -lt 8 ]; then
    nr_die "administrator password must be at least 8 characters"
  fi

  nr_info "creating the first administrator: $email"
  if [ "$NR_DRY_RUN" = "1" ]; then
    nr_run_compose run --rm -T api node scripts/create-admin.js --email "$email" --password-stdin
  else
    nr_run_compose_with_stdin "$password" run --rm -T api node scripts/create-admin.js --email "$email" --password-stdin
    nr_state_set ADMIN_CREATED 1
  fi

  if [ "$generated" = "1" ] && [ "$NR_DRY_RUN" = "0" ]; then
    NR_ADMIN_PASSWORD_PRINTED="$password"
    NR_ADMIN_STATE="created"
  elif [ "$NR_DRY_RUN" = "1" ]; then
    NR_ADMIN_STATE="would-create"
  else
    NR_ADMIN_STATE="created"
  fi
  NR_ADMIN_EMAIL_VALUE="$email"
  unset password
}

# S11: one summary box with the panel URL, the administrator and the lifecycle
# commands. The generated password is printed here once and never written.
nr_print_summary() {
  local port mode profile status
  port="$(nr_env_get PANEL_PORT)"
  port="${port:-8080}"
  if [ -n "$NR_PORT_OVERRIDE" ]; then
    port="$NR_PORT_OVERRIDE"
  fi
  mode="$(nr_env_get NEWSROOM_MODE)"
  mode="${mode:-$NR_RUN_MODE}"
  profile="$NR_PROFILE"
  [ "$profile" = "auto" ] && profile="cpu"
  if [ "$NR_START_STACK" = "0" ] || [ "$NR_DRY_RUN" = "1" ]; then
    status="not started"
  else
    status="running"
  fi

  printf '\n'
  printf '+----------------------------------------------------------------------+\n'
  printf '| %-68s |\n' "Newsroom installation summary"
  printf '+----------------------------------------------------------------------+\n'
  printf '| %-68s |\n' "Panel:    http://127.0.0.1:${port} (${status})"
  printf '| %-68s |\n' "Mode:     ${mode}"
  printf '| %-68s |\n' "Profile:  ${profile}"
  printf '| %-68s |\n' "Admin:    ${NR_ADMIN_EMAIL_VALUE:-admin@example.local}"
  if [ -n "$NR_ADMIN_PASSWORD_PRINTED" ]; then
    printf '| %-68s |\n' "Generated administrator password (shown once):"
    printf '| %-68s |\n' "$NR_ADMIN_PASSWORD_PRINTED"
  elif [ "$NR_ADMIN_STATE" = "created" ]; then
    printf '| %-68s |\n' "Password: the one you entered during installation"
  elif [ "$NR_DRY_RUN" = "1" ]; then
    printf '| %-68s |\n' "Password: not created in a dry run"
  else
    printf '| %-68s |\n' "Password: unchanged from the previous installation"
  fi
  printf '| %-68s |\n' "Start:    newsroom up"
  printf '| %-68s |\n' "Stop:     newsroom down"
  printf '| %-68s |\n' "Logs:     newsroom logs [service]"
  printf '| %-68s |\n' "Health:   newsroom doctor"
  printf '+----------------------------------------------------------------------+\n'
  printf '\n'
  NR_ADMIN_PASSWORD_PRINTED=""
}

nr_start_stack() {
  if [ "$NR_START_STACK" = "0" ]; then
    nr_info "skipping stack start (--no-start)"
    return 0
  fi
  nr_info "building and starting the stack (profile: $NR_PROFILE)"
  nr_run_compose up -d --build
  nr_state_set STACK_STARTED 1
  nr_state_set PROFILE "$NR_PROFILE"
  nr_state_set INSTALLED_AT "$(nr_now)"
  nr_ok "stack is running"
}

nr_open_panel() {
  local port
  port="$(nr_env_get PANEL_PORT)"
  port="${port:-8080}"
  if [ "$NR_OPEN_PANEL" = "0" ] || [ "$NR_DRY_RUN" = "1" ]; then
    nr_info "open the panel at http://127.0.0.1:${port}"
    return 0
  fi
  if nr_command_exists xdg-open; then
    xdg-open "http://127.0.0.1:${port}" >/dev/null 2>&1 || true
  elif nr_command_exists open; then
    open "http://127.0.0.1:${port}" >/dev/null 2>&1 || true
  fi
  nr_info "open the panel at http://127.0.0.1:${port}"
}

# --- Uninstall -------------------------------------------------------------

# S11: --purge always asks for the literal word "delete", even with --yes.
# --force-purge is the explicit opt-out for unattended automation.
nr_purge_confirmed() {
  if [ "$NR_FORCE_PURGE" = "1" ]; then
    nr_warn "force-purge: deleting volumes, local models and .env without confirmation"
    return 0
  fi
  local answer=""
  if [ -t 0 ] && [ -t 2 ]; then
    printf "Type 'delete' to permanently delete volumes, local models and .env: " >&2
  else
    # Non-interactive stdin may still carry a deliberate confirmation (tests,
    # automation), but never block forever waiting for one.
    local probe=""
    if ! IFS= read -r -t 0 probe; then
      nr_warn "purge requires the typed confirmation; pass --force-purge for non-interactive use"
      return 1
    fi
  fi
  if ! IFS= read -r answer; then
    nr_warn "no confirmation input; keeping volumes, local models and .env (pass --force-purge for non-interactive use)"
    return 1
  fi
  if [ "$answer" != "delete" ]; then
    nr_info "confirmation did not match 'delete'; keeping volumes, local models and .env"
    return 1
  fi
  return 0
}

nr_uninstall() {
  local purge="$1"
  nr_info "removing the Newsroom stack"
  if [ -f "$NR_COMPOSE_FILE" ]; then
    nr_run_compose down --remove-orphans || nr_warn "docker compose down reported an error"
  else
    nr_warn "compose file not found; no containers were removed"
  fi

  local delete_data=0
  if [ "$purge" = "1" ]; then
    if nr_purge_confirmed; then
      delete_data=1
    fi
  fi

  if [ "$delete_data" = "1" ] && [ "$NR_DRY_RUN" = "0" ]; then
    nr_run_compose down --volumes --rmi local --remove-orphans || nr_warn "docker compose down --volumes reported an error"
    rm -rf "$NR_STATE_DIR"
    rm -f "$NR_ENV_FILE"
    nr_ok "volumes, local models, images and .env removed"
  fi

  if [ -n "$NR_BIN_DIR" ] && [ "$NR_DRY_RUN" = "0" ]; then
    rm -f "$NR_BIN_DIR/newsroom"
    nr_ok "removed CLI from $NR_BIN_DIR"
  fi

  nr_ok "uninstall complete"
}
